// TH16 v1.00a Stage 4 boss non-spell Boss2 (st04bs.ecl.txt:173-236).
// type 11 -> TH16_TALISMAN, approved alias of the identical TH18 slot (bullet-types.md).

const TH16_TALISMAN: int = 528;

const TIME_LIMIT: int = 2404;
const OPENING_BUFFER: int = 120;

// Source EX record 1: ANGLE_ACCEL a=120, r=speed increment/frame, s=angle increment/frame.
xformdef ANGLE_ACCEL(spin: angle, accel: fx) {
    set_ang_vel(spin);
    @120 set_accel(accel);
    set_ang_vel(0deg);
    set_accel(0fx);
}

// moveRand(412) port of the verified recipe (movement.md); this card's
// moveLimit(0,128,280,96) => field x[-140,140] y[80,176], inner box x+-70 y[104,152].
// Enemy int slot 0 = step count, fx slot 0/1 = logical unit direction.
sub card_arm_next_step(dur: int, v0: fx) {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < dur { speed = v0 * ((dur - k) as fx) / (dur as fx); }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 80fx { ny = 80fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

// Source Boss2_1144 / Boss2_1496 moveRand calls.
sub card_move_rand(dur: int, v0: fx) {
    var r: int = rand(65536) - 32768;
    var a: int = 0;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 104fx {
        if a < 0 { a = -a; }
    } else if $self_y > 152fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    card_arm_next_step(dur, v0);
}

// Source wait(n) inside the moveRand-driven stretch; advances one movement step per frame.
sub card_wait(frames: int, dur: int, v0: fx) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step(dur, v0);
    }
}

// Boss2_at: one emitter, 5 rings 10 frames apart; base angle stepped by ring_step after each fire.
async sub boss2_at(id: int, color: int, ring_step: angle, spin: angle, count: int, accel: fx) {
    sh_reset(id);
    sh_sprite(id, TH16_TALISMAN, color);
    sh_ring(id, 1);
    sh_aim(id, 0);
    sh_count(id, count, 1);
    sh_speed(id, 0.5fx, 0fx);
    sh_offset(id, 0fx, -16fx);
    sh_dist(id, 30fx);            // etDist 32 - ANIM retreat 4*0.5
    sh_xform(id, ANGLE_ACCEL(spin, accel));
    var base: angle = 90deg;      // source E init 1.570796
    for k in 0..5 {
        sh_angle(id, base, 0deg);
        sh_fire(id);
        base = base + ring_step;
        wait(10);
    }
}

async sub source_enemy() {
    set_invuln(65535);
    set_hitbox(24fx);             // source setHitbox(48,48)
    set_hurtbox(20fx);            // source setHurtbox(40,40)
    wait(120);                    // source wait(60)+wait(60); anmPlay/playSound omitted

    // Boss2_at difficulty masks: count 7/13/19/19, spin D=1deg (L: 1.2deg), r 0.02 (L: 0.025).
    var count: int = 19;
    var spin: angle = 1deg;
    var accel: fx = 0.02fx;
    if global(GVAR_RANK) == RANK_EASY { count = 7; }
    if global(GVAR_RANK) == RANK_NORMAL { count = 13; }
    if global(GVAR_RANK) == RANK_LUNATIC { spin = 1.2deg; accel = 0.025fx; }

    loop {
        card_move_rand(240, 0.5fx);
        var n: int = 3;           // source $A = 3, if ($A--) => 3 iterations
        while n > 0 {
            spawn boss2_at(0, 2, 3deg, spin, count, accel);
            card_wait(25, 240, 0.5fx);
            spawn boss2_at(1, 4, 0deg - 3deg, 0deg - spin, count, accel);
            card_wait(25, 240, 0.5fx);
            n = n - 1;
        }
        card_move_rand(60, 1.0fx);
        card_wait(60, 60, 1.0fx);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 1000, 0, 0, 0, source_enemy);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
